mapper.select:
SELECT COALESCE(max(version_no), 0) + 1
FROM public.attendance_policy_version
WHERE department_id = #{departmentId}

SELECT id, department_id, name, check_in_start_time, status
FROM public.attendance_policy_version
WHERE id = #{policyVersionId}
  AND department_id = #{departmentId}
  AND status = 'DRAFT'
FOR UPDATE

mapper.update:
UPDATE public.attendance_policy_version
SET name = #{name},
	check_in_start_time = #{checkInStartTime}
WHERE id = #{policyVersionId}
  AND department_id = #{departmentId}
  AND status = 'DRAFT'

UPDATE public.attendance_policy_version
SET status = 'PUBLISHED',
	published_by_account_id = #{actorAccountId},
	published_at = #{publishedAt}
WHERE id = #{policyVersionId}
  AND department_id = #{departmentId}
  AND status = 'DRAFT'

